<template><MarketingList title="Кампании" eyebrow="CAMPAIGNS"><template #actions><button class="primary" @click="create">Создать AI-кампанию</button></template><div class="cards"><article v-for="c in campaigns" :key="c.id" class="card"><div class="top"><span class="status" :class="c.status">{{ labels[c.status] }}</span><span>{{ c.channels.join(' · ') }}</span></div><h2>{{ c.name }}</h2><p>{{ c.objective }}</p><div class="content"><strong>{{ c.content.title }}</strong><small>{{ c.content.body }}</small></div></article></div></MarketingList></template>
<script setup lang="ts">
definePageMeta({ layout: 'admin', middleware: ['admin'] })
const api=useApi(); const campaigns=ref<any[]>([]); const labels:any={draft:'Черновик',scheduled:'Запланирована',active:'Активна',paused:'Пауза',completed:'Завершена'}; const load=async()=>{const r=await api<any>('/api/marketing/campaigns');campaigns.value=r.items||[]}; const create=async()=>{await api('/api/marketing/campaigns/from-brief',{method:'POST',body:{name:'Turkey Summer Push',objective:'Увеличить бронирования Турции',channels:['email','telegram','onsite']}}); await load()}; onMounted(load)</script>
<style scoped>.cards{display:grid;grid-template-columns:repeat(2,1fr);gap:14px}.card{background:#fff;border:1px solid #dfe5e1;border-radius:16px;padding:20px}.top{display:flex;justify-content:space-between;color:#738078;font:600 11px Inter}.status{padding:5px 8px;border-radius:7px;background:#eef2ef}.status.active{background:#eaf7f0;color:#188054}.card h2{font:800 24px Manrope;margin:16px 0 7px}.card p,.content small{font:14px/1.6 Inter;color:#6d7973}.content{margin-top:20px;padding-top:15px;border-top:1px solid #e7ebe8}.content strong,.content small{display:block}.content strong{font:700 13px Inter;margin-bottom:5px}.primary{background:#17382c;color:#fff;border:0;border-radius:10px;padding:11px 15px;font:700 12px Inter}@media(max-width:700px){.cards{grid-template-columns:1fr}}</style>
